class Solution {
public:
    vector<int> countOppositeParity(vector<int>& nums) {
        int even = 0, odd = 0;
        for (int x : nums) (x % 2 ? odd : even)++;
        vector<int> ans;
        for (int x : nums) {
            if (x % 2) { --odd; ans.push_back(even); }
            else { --even; ans.push_back(odd); }
        }
        return ans;
    }
};
